final tileProvider = MbTilesTileProvider.fromPath(path: 'path/to/file.mbtiles');

@override
Widget build(BuildContext context) {
  return FlutterMap(
    options: const MapOptions(),
    children: [
      TileLayer(tileProvider: tileProvider),
    ],
  );
}

@override
void dispose() {
  tileProvider.dispose();
  super.dispose();
}
